import yaml
import pickle

class Node:
    def __init__(self):
        self.children = {}

def to_node(data):
    if isinstance(data, dict):
        flattened = yaml.load(data)
        name = flattened['a']
        value = flattened['b']
        item = Node()
        item.children[name] = value
        return item
    elif isinstance(data, list):
        flattened = yaml.load(data)
        items = [to_node(item) for item in flattened]
        return Node(val=items)
    else:
        return data

def from_node(node):
    if isinstance(node, Node):
        if 'children' in node:
            for key, value in node.children.items():
                if isinstance(value, dict):
                    value = from_node(value)
            return value
        else:
            return None
    else:
        return {}

